#!/bin/bash
set -euo pipefail

if [ $# -ne 2 ]; then
  echo "Usage: $0 <IMS_ACCESS_TOKEN> <CMU_URL>" >&2
  echo "Example: $0 '<ims-access-token>' 'https://cm-reports.adobeprimetime.com/v2/year?tenant=NBA&start=2026-01-01&end=2026-01-31'" >&2
  exit 1
fi

for cmd in curl jq grep sed awk base64 node mktemp tar; do
  if ! command -v "$cmd" >/dev/null 2>&1; then
    echo "Missing required command: $cmd" >&2
    exit 1
  fi
done

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TMP_DIR="$(mktemp -d "${TMPDIR:-/tmp}/cmuhtml2.XXXXXX")"
EMBEDDED_DIR="$TMP_DIR/embedded"
DISCOVERED_NDJSON="$TMP_DIR/discovered.ndjson"
DISCOVERED_JSON="$TMP_DIR/discovered.json"
OUTPUT_HTML="$TMP_DIR/output.html"
RENDER_DISCOVERED_JSON="$TMP_DIR/discovered-render.json"
: > "$DISCOVERED_NDJSON"

PROGRESS_COUNT=0
SUCCESS_COUNT=0
FAIL_COUNT=0
SPINNER='|/-\'
CMU_INTERRUPT_REQUESTED=0

cleanup() {
  rm -rf "$TMP_DIR"
}

extract_embedded_assets() {
  local archive_path="$TMP_DIR/cmuhtml2-embedded.tar.gz"
  mkdir -p "$EMBEDDED_DIR"

  if printf '%s' "$CMU_EMBEDDED_ARCHIVE_B64" | base64 --decode > "$archive_path" 2>/dev/null; then
    :
  elif printf '%s' "$CMU_EMBEDDED_ARCHIVE_B64" | base64 -D > "$archive_path" 2>/dev/null; then
    :
  else
    echo "Unable to decode embedded clickCMU asset bundle." >&2
    exit 1
  fi

  if ! tar -xzf "$archive_path" -C "$EMBEDDED_DIR"; then
    echo "Unable to extract embedded clickCMU asset bundle." >&2
    exit 1
  fi
}

progress_tick() {
  PROGRESS_COUNT=$((PROGRESS_COUNT + 1))
  local i=$((PROGRESS_COUNT % 4))
  printf "\r[%c] Crawling CMU tree... (%d)" "${SPINNER:$i:1}" "$PROGRESS_COUNT" >&2
}

progress_done() {
  local status=$?
  if [ "$status" -eq 0 ] && [ "$CMU_INTERRUPT_REQUESTED" = "1" ]; then
    printf "\r[!] Crawl interrupted. Exported partial clickCMU with %d CMU nodes processed (%d ok, %d failed).\n" "$PROGRESS_COUNT" "$SUCCESS_COUNT" "$FAIL_COUNT" >&2
  elif [ "$status" -eq 0 ]; then
    printf "\r[✓] Crawl complete. %d CMU nodes processed (%d ok, %d failed).\n" "$PROGRESS_COUNT" "$SUCCESS_COUNT" "$FAIL_COUNT" >&2
  else
    printf "\r[!] Crawl failed after %d CMU nodes (%d ok, %d failed).\n" "$PROGRESS_COUNT" "$SUCCESS_COUNT" "$FAIL_COUNT" >&2
  fi
  cleanup
}

request_partial_export() {
  if [ "$CMU_INTERRUPT_REQUESTED" = "1" ]; then
    return 0
  fi
  CMU_INTERRUPT_REQUESTED=1
  CMU_ABORT_CRAWL=1
  printf "\nInterrupt received. Finishing current node and exporting partial clickCMU.\n" >&2
}

trap progress_done EXIT
trap request_partial_export INT TERM

read -r -d '' CMU_EMBEDDED_ARCHIVE_B64 <<'__CMUHTML2_EMBEDDED_ARCHIVE__' || true

__CMUHTML2_EMBEDDED_ARCHIVE__

extract_embedded_assets
CMU_EMBEDDED_RENDER_HELPER="$EMBEDDED_DIR/render_clickcmu_underpar.mjs"
CMU_EMBEDDED_RUNTIME_PATCH_HTML="$EMBEDDED_DIR/clickCMU-runtime-patch-underpar.html"
CMU_EMBEDDED_TEMPLATE_HTML="$EMBEDDED_DIR/clickESM-template.html"
CMU_EMBEDDED_FALLBACK_CATALOG="$EMBEDDED_DIR/click-cmu-endpoints.json"
CMU_LOCAL_RENDER_HELPER="$SCRIPT_DIR/bak/render_clickcmu_underpar.mjs"
CMU_LOCAL_RUNTIME_PATCH_HTML="$SCRIPT_DIR/bak/clickCMU-runtime-patch-underpar.html"
CMU_LOCAL_TEMPLATE_HTML="$SCRIPT_DIR/bak/clickESM-template.html"
CMU_LOCAL_FALLBACK_CATALOG="$SCRIPT_DIR/bak/click-cmu-endpoints.json"

CMU_MGMT_BASE_URL="${CMU_MGMT_BASE_URL:-https://mgmt.auth.adobe.com}"
CMU_REPORTS_BASE_URL="${CMU_REPORTS_BASE_URL:-https://cm-reports.adobeprimetime.com}"
CMU_CRAWL_ROW_LIMIT="${CMU_CRAWL_ROW_LIMIT:-1}"
CMU_ACCESS_TOKEN="${CMU_ACCESS_TOKEN:-}"
CMU_IMS_CLIENT_ID="${CMU_IMS_CLIENT_ID:-cm-console-ui}"
CMU_INCLUDE_CLIENT_ID_HEADER="${CMU_INCLUDE_CLIENT_ID_HEADER:-1}"
CMU_FAIL_FAST_AUTH_ERRORS="${CMU_FAIL_FAST_AUTH_ERRORS:-1}"
CMU_SUPPRESS_AUTH_ERROR_NODES="${CMU_SUPPRESS_AUTH_ERROR_NODES:-1}"
CMU_STOP_BEFORE_TOKEN_EXPIRY_MS="${CMU_STOP_BEFORE_TOKEN_EXPIRY_MS:-45000}"
CMU_TRY_FALLBACK_BASE="${CMU_TRY_FALLBACK_BASE:-1}"
CMU_INCLUDE_BROWSER_HEADERS="${CMU_INCLUDE_BROWSER_HEADERS:-1}"
CMU_ORIGIN_HEADER="${CMU_ORIGIN_HEADER:-https://cdn.experience.adobe.net}"
CMU_REFERER_HEADER="${CMU_REFERER_HEADER:-https://cdn.experience.adobe.net/}"
CMU_EXPECTED_CLIENT_ID="${CMU_EXPECTED_CLIENT_ID:-cm-console-ui}"
CMU_IMS_CHECK_SCOPE_DEFAULT="${CMU_IMS_CHECK_SCOPE_DEFAULT:-AdobeID,openid,dma_group_mapping,read_organizations,additional_info.projectedProductContext}"
CMU_TENANT_SCOPE="${CMU_TENANT_SCOPE:-}"
CMU_PROGRAMMER_ID="${CMU_PROGRAMMER_ID:-}"
CMU_PROGRAMMER_LABEL="${CMU_PROGRAMMER_LABEL:-}"
CMU_CLICK_TEMPLATE_HTML="${CMU_CLICK_TEMPLATE_HTML:-}"
CMU_CLICK_FALLBACK_CATALOG="${CMU_CLICK_FALLBACK_CATALOG:-}"
DEFAULT_CMU_RENDER_HELPER="$CMU_EMBEDDED_RENDER_HELPER"
DEFAULT_CMU_RUNTIME_PATCH_HTML="$CMU_EMBEDDED_RUNTIME_PATCH_HTML"
DEFAULT_CMU_CLICK_TEMPLATE_HTML="$CMU_EMBEDDED_TEMPLATE_HTML"
DEFAULT_CMU_CLICK_FALLBACK_CATALOG="$CMU_EMBEDDED_FALLBACK_CATALOG"

if [ -f "$CMU_LOCAL_RENDER_HELPER" ]; then
  DEFAULT_CMU_RENDER_HELPER="$CMU_LOCAL_RENDER_HELPER"
fi
if [ -f "$CMU_LOCAL_RUNTIME_PATCH_HTML" ]; then
  DEFAULT_CMU_RUNTIME_PATCH_HTML="$CMU_LOCAL_RUNTIME_PATCH_HTML"
fi
if [ -f "$CMU_LOCAL_TEMPLATE_HTML" ]; then
  DEFAULT_CMU_CLICK_TEMPLATE_HTML="$CMU_LOCAL_TEMPLATE_HTML"
fi
if [ -f "$CMU_LOCAL_FALLBACK_CATALOG" ]; then
  DEFAULT_CMU_CLICK_FALLBACK_CATALOG="$CMU_LOCAL_FALLBACK_CATALOG"
fi

CMU_RENDER_HELPER="${CMU_RENDER_HELPER:-$DEFAULT_CMU_RENDER_HELPER}"
CMU_RUNTIME_PATCH_HTML="${CMU_RUNTIME_PATCH_HTML:-$DEFAULT_CMU_RUNTIME_PATCH_HTML}"
CMU_CLICK_TEMPLATE_HTML="${CMU_CLICK_TEMPLATE_HTML:-$DEFAULT_CMU_CLICK_TEMPLATE_HTML}"
CMU_CLICK_FALLBACK_CATALOG="${CMU_CLICK_FALLBACK_CATALOG:-$DEFAULT_CMU_CLICK_FALLBACK_CATALOG}"

ARG_INPUT_TOKEN="$1"
START_URL="$2"
START_PATH_RAW="${START_URL%%\?*}"
START_QUERY=""
if [[ "$START_URL" == *\?* ]]; then
  START_QUERY="${START_URL#*\?}"
fi

sanitize_inherited_query() {
  local raw_query="$1"
  local cleaned=""
  local part key

  [ -z "$raw_query" ] && return 0

  IFS='&' read -r -a parts <<< "$raw_query"
  for part in "${parts[@]}"; do
    [ -z "$part" ] && continue
    key="${part%%=*}"
    case "$key" in
      format|limit|access_token) continue ;;
    esac
    if [ -n "$cleaned" ]; then
      cleaned="${cleaned}&${part}"
    else
      cleaned="$part"
    fi
  done

  printf '%s' "$cleaned"
}

sanitize_drill_context_query() {
  local raw_query="$1"
  local cleaned=""
  local part key

  [ -z "$raw_query" ] && return 0

  IFS='&' read -r -a parts <<< "$raw_query"
  for part in "${parts[@]}"; do
    [ -z "$part" ] && continue
    key="${part%%=*}"
    case "$key" in
      format|limit|access_token|start|end|metrics) continue ;;
    esac
    if [ -n "$cleaned" ]; then
      cleaned="${cleaned}&${part}"
    else
      cleaned="$part"
    fi
  done

  printf '%s' "$cleaned"
}

query_has_key() {
  local raw_query="$1"
  local wanted="$2"
  local part key

  [ -z "$raw_query" ] && return 1
  IFS='&' read -r -a parts <<< "$raw_query"
  for part in "${parts[@]}"; do
    [ -z "$part" ] && continue
    key="${part%%=*}"
    if [ "$key" = "$wanted" ]; then
      return 0
    fi
  done
  return 1
}

query_value_for_key() {
  local raw_query="$1"
  local wanted="$2"
  local part key value

  [ -z "$raw_query" ] && return 1
  IFS='&' read -r -a parts <<< "$raw_query"
  for part in "${parts[@]}"; do
    [ -z "$part" ] && continue
    key="${part%%=*}"
    value="${part#*=}"
    if [ "$key" = "$wanted" ]; then
      printf '%s' "$value"
      return 0
    fi
  done
  return 1
}

query_has_tenant_scope() {
  local raw_query="$1"
  query_has_key "$raw_query" "tenant" || query_has_key "$raw_query" "tenant_id" || query_has_key "$raw_query" "tenant-id"
}

capture_tenant_scope_candidate() {
  local raw_candidate="$1"
  local candidate

  candidate="$(printf '%s' "$raw_candidate" | sed -E 's/^[[:space:]]+//; s/[[:space:]]+$//')"
  [ -n "$candidate" ] || return 0

  if [ -z "$CMU_TENANT_SCOPE" ]; then
    CMU_TENANT_SCOPE="$candidate"
  fi
  if [ -z "$CMU_PROGRAMMER_ID" ]; then
    CMU_PROGRAMMER_ID="$candidate"
  fi
  if [ -z "$CMU_PROGRAMMER_LABEL" ]; then
    CMU_PROGRAMMER_LABEL="$candidate"
  fi
}

capture_tenant_scope_from_query() {
  local raw_query="$1"
  local candidate=""

  candidate="$(query_value_for_key "$raw_query" "tenant" || true)"
  if [ -z "$candidate" ]; then
    candidate="$(query_value_for_key "$raw_query" "tenant_id" || true)"
  fi
  if [ -z "$candidate" ]; then
    candidate="$(query_value_for_key "$raw_query" "tenant-id" || true)"
  fi
  capture_tenant_scope_candidate "$candidate"
}

capture_tenant_scope_from_url() {
  local raw="$1"
  local raw_query=""

  [ -n "$raw" ] || return 0
  if [[ "$raw" == *\?* ]]; then
    raw_query="${raw#*\?}"
    capture_tenant_scope_from_query "$raw_query"
  fi
}

query_add_kv() {
  local raw_query="$1"
  local key="$2"
  local value="$3"

  if query_has_key "$raw_query" "$key"; then
    printf '%s' "$raw_query"
    return 0
  fi

  if [ -n "$raw_query" ]; then
    printf '%s&%s=%s' "$raw_query" "$key" "$value"
  else
    printf '%s=%s' "$key" "$value"
  fi
}

merge_query_strings() {
  local primary_query="$1"
  local secondary_query="$2"
  local merged cleaned_secondary part key value

  merged="$(sanitize_inherited_query "$primary_query")"
  cleaned_secondary="$(sanitize_inherited_query "$secondary_query")"
  [ -n "$cleaned_secondary" ] || {
    printf '%s' "$merged"
    return 0
  }

  IFS='&' read -r -a parts <<< "$cleaned_secondary"
  for part in "${parts[@]}"; do
    [ -n "$part" ] || continue
    key="${part%%=*}"
    value="${part#*=}"
    merged="$(query_add_kv "$merged" "$key" "$value")"
  done

  printf '%s' "$merged"
}

url_with_query() {
  local base="$1"
  local query="$2"

  if [ -n "$query" ]; then
    printf '%s?%s' "$base" "$query"
  else
    printf '%s' "$base"
  fi
}

query_from_url() {
  local raw="$1"

  if [[ "$raw" == *\?* ]]; then
    printf '%s' "${raw#*\?}"
  fi
}

base_url_from_absolute_url() {
  local raw="$1"
  local without_scheme host

  case "$raw" in
    http://*|https://*)
      without_scheme="${raw#*://}"
      host="${without_scheme%%/*}"
      if [[ "$raw" == http://* ]]; then
        printf 'http://%s' "$host"
      else
        printf 'https://%s' "$host"
      fi
      return 0
      ;;
  esac
  return 1
}

is_mgmt_base_url() {
  local base="$1"
  [[ "$base" == *"mgmt.auth.adobe.com"* ]]
}

normalize_cmu_api_path() {
  local raw="$1"
  local cleaned="${raw%.json}"
  local path without_scheme

  case "$cleaned" in
    http://*|https://*)
      without_scheme="${cleaned#*://}"
      path="/${without_scheme#*/}"
      ;;
    /*) path="$cleaned" ;;
    *) path="/$cleaned" ;;
  esac

  path="${path%%\?*}"
  path="$(printf '%s' "$path" | sed -E 's#//+#/#g')"
  path="${path%.json}"

  if [[ "$path" =~ ^/cmu/v2(/.*)?$ ]]; then
    path="/v2${BASH_REMATCH[1]}"
  fi

  printf '%s' "$path"
}

path_for_base_url() {
  local base="$1"
  local api_path="$2"

  if is_mgmt_base_url "$base"; then
    if [[ "$api_path" =~ ^/v2(/.*)?$ ]]; then
      printf '/cmu%s' "$api_path"
      return 0
    fi
  else
    if [[ "$api_path" =~ ^/cmu/v2(/.*)?$ ]]; then
      printf '/v2%s' "${BASH_REMATCH[1]}"
      return 0
    fi
  fi

  printf '%s' "$api_path"
}

normalize_to_base_url() {
  local raw="$1"
  local base="$2"
  local api_path base_path

  api_path="$(normalize_cmu_api_path "$raw")"
  base_path="$(path_for_base_url "$base" "$api_path")"
  printf '%s%s' "${base%/}" "$base_path"
}

is_cmu_dimension_segment() {
  case "$1" in
    year|month|day|hour|minute|duration|occurrences|activity-level|application|rule|policy|policy-id|tenant|application-id|concurrency-level|mvpd)
      return 0
      ;;
  esac
  return 1
}

rewrite_legacy_tenant_path() {
  local path="$1"
  local prefix tenant remainder
  REWRITTEN_START_PATH="$path"

  if [[ "$path" =~ ^(https?://[^/]+/(cmu/v2|v2))/([^/?#]+)/(.+)$ ]]; then
    prefix="${BASH_REMATCH[1]}"
    tenant="${BASH_REMATCH[3]}"
    remainder="${BASH_REMATCH[4]}"
  elif [[ "$path" =~ ^/(cmu/v2|v2)/([^/?#]+)/(.+)$ ]]; then
    prefix="/${BASH_REMATCH[1]}"
    tenant="${BASH_REMATCH[2]}"
    remainder="${BASH_REMATCH[3]}"
  else
    return 0
  fi

  if ! is_cmu_dimension_segment "$tenant"; then
    if ! query_has_key "$INHERITED_QUERY" "tenant"; then
      if [ -n "$INHERITED_QUERY" ]; then
        INHERITED_QUERY="tenant=${tenant}&${INHERITED_QUERY}"
      else
        INHERITED_QUERY="tenant=${tenant}"
      fi
    fi
    REWRITTEN_START_PATH="${prefix}/${remainder%/}"
  fi
}

decode_jwt_payload_json() {
  local jwt="$1"
  local payload b64 rem

  [ -n "$jwt" ] || return 1
  payload="$(printf '%s' "$jwt" | awk -F'.' '{print $2}')"
  [ -n "$payload" ] || return 1

  b64="${payload//-/+}"
  b64="${b64//_//}"
  rem=$(( ${#b64} % 4 ))
  if [ "$rem" -eq 2 ]; then
    b64="${b64}=="
  elif [ "$rem" -eq 3 ]; then
    b64="${b64}="
  elif [ "$rem" -eq 1 ]; then
    return 1
  fi

  if printf '%s' "$b64" | base64 --decode >/dev/null 2>&1; then
    printf '%s' "$b64" | base64 --decode 2>/dev/null || return 1
  else
    printf '%s' "$b64" | base64 -D 2>/dev/null || return 1
  fi
}

jwt_claim() {
  local jwt="$1"
  local key="$2"
  local payload

  payload="$(decode_jwt_payload_json "$jwt" 2>/dev/null)" || return 1
  printf '%s' "$payload" | jq -r --arg key "$key" '.[$key] // empty' 2>/dev/null || return 1
}

format_unix_ms_utc() {
  local ms="$1"
  local sec

  [[ "$ms" =~ ^[0-9]+$ ]] || return 1
  sec=$((ms / 1000))
  if date -u -r "$sec" '+%Y-%m-%dT%H:%M:%SZ' >/dev/null 2>&1; then
    date -u -r "$sec" '+%Y-%m-%dT%H:%M:%SZ'
  else
    date -u -d "@$sec" '+%Y-%m-%dT%H:%M:%SZ'
  fi
}

INHERITED_QUERY="$(sanitize_inherited_query "$START_QUERY")"
START_PATH="$START_PATH_RAW"
rewrite_legacy_tenant_path "$START_PATH"

START_BASE_FROM_INPUT="$(base_url_from_absolute_url "$START_PATH_RAW" || true)"
if [ -n "$START_BASE_FROM_INPUT" ]; then
  CMU_PRIMARY_BASE_URL="${CMU_PRIMARY_BASE_URL:-$START_BASE_FROM_INPUT}"
else
  CMU_PRIMARY_BASE_URL="${CMU_PRIMARY_BASE_URL:-$CMU_REPORTS_BASE_URL}"
fi
CMU_PRIMARY_BASE_URL="${CMU_PRIMARY_BASE_URL%/}"

if [ "$CMU_PRIMARY_BASE_URL" = "${CMU_MGMT_BASE_URL%/}" ]; then
  CMU_FALLBACK_BASE_URL="${CMU_FALLBACK_BASE_URL:-${CMU_REPORTS_BASE_URL%/}}"
elif [ "$CMU_PRIMARY_BASE_URL" = "${CMU_REPORTS_BASE_URL%/}" ]; then
  CMU_FALLBACK_BASE_URL="${CMU_FALLBACK_BASE_URL:-${CMU_MGMT_BASE_URL%/}}"
else
  CMU_FALLBACK_BASE_URL="${CMU_FALLBACK_BASE_URL:-${CMU_REPORTS_BASE_URL%/}}"
fi
CMU_FALLBACK_BASE_URL="${CMU_FALLBACK_BASE_URL%/}"
START_PATH="$(normalize_to_base_url "$REWRITTEN_START_PATH" "$CMU_PRIMARY_BASE_URL")"

if [ ! -f "$CMU_RENDER_HELPER" ]; then
  echo "Missing render helper: $CMU_RENDER_HELPER" >&2
  exit 1
fi
if [ ! -f "$CMU_RUNTIME_PATCH_HTML" ]; then
  echo "Missing clickCMU runtime patch: $CMU_RUNTIME_PATCH_HTML" >&2
  exit 1
fi
if [ ! -f "$CMU_CLICK_TEMPLATE_HTML" ]; then
  echo "Unable to locate clickCMU base template." >&2
  echo "Set CMU_CLICK_TEMPLATE_HTML to an alternate template if you need to override the embedded one." >&2
  exit 1
fi

TOKEN="${CMU_ACCESS_TOKEN:-$ARG_INPUT_TOKEN}"
TOKEN="${TOKEN#Bearer }"
TOKEN="${TOKEN#bearer }"
TOKEN="$(printf '%s' "$TOKEN" | sed -E 's/^[[:space:]]+//; s/[[:space:]]+$//')"
if [ -z "$TOKEN" ]; then
  echo "Missing IMS access token input." >&2
  exit 1
fi

TOKEN_TYPE="$(jwt_claim "$TOKEN" "type" || true)"
if [ "$TOKEN_TYPE" != "access_token" ]; then
  echo "Input token is not an IMS access_token (claim type='$TOKEN_TYPE')." >&2
  echo "Pass a live IMS bearer token from Adobe Pass console network traffic." >&2
  exit 1
fi

CID="$(jwt_claim "$TOKEN" "client_id" || true)"
IMS_CLIENT_ID="$CID"
if [ -z "$IMS_CLIENT_ID" ]; then
  IMS_CLIENT_ID="$CMU_IMS_CLIENT_ID"
fi
IMS_USER_ID="$(jwt_claim "$TOKEN" "user_id" || true)"
IMS_SCOPE="$(jwt_claim "$TOKEN" "scope" || true)"
if [ -z "$IMS_SCOPE" ]; then
  IMS_SCOPE="$CMU_IMS_CHECK_SCOPE_DEFAULT"
fi

AUTH_HEADER_ARGS=(-H "Authorization: Bearer $TOKEN" -H "Accept: application/json")
if [ "$CMU_INCLUDE_CLIENT_ID_HEADER" = "1" ] && [ -n "$IMS_CLIENT_ID" ]; then
  AUTH_HEADER_ARGS+=(-H "client_id: $IMS_CLIENT_ID" -H "x-api-key: $IMS_CLIENT_ID")
fi
if [ "$CMU_INCLUDE_BROWSER_HEADERS" = "1" ]; then
  AUTH_HEADER_ARGS+=(-H "Origin: ${CMU_ORIGIN_HEADER}" -H "Referer: ${CMU_REFERER_HEADER}")
fi
if [ -n "$CMU_EXPECTED_CLIENT_ID" ] && [ -n "$CID" ] && [ "$CID" != "$CMU_EXPECTED_CLIENT_ID" ]; then
  echo "Warning: token client_id='${CID}', expected '${CMU_EXPECTED_CLIENT_ID}' for CMU console tokens." >&2
fi

TOKEN_EXPIRES_AT_MS=""
TOKEN_CREATED_AT_MS="$(jwt_claim "$TOKEN" "created_at" || true)"
TOKEN_EXPIRES_IN_MS="$(jwt_claim "$TOKEN" "expires_in" || true)"
if [[ "${TOKEN_CREATED_AT_MS}" =~ ^[0-9]+$ ]] && [[ "${TOKEN_EXPIRES_IN_MS}" =~ ^[0-9]+$ ]]; then
  TOKEN_EXPIRES_AT_MS=$((TOKEN_CREATED_AT_MS + TOKEN_EXPIRES_IN_MS))
  NOW_MS=$(( $(date +%s) * 1000 ))
  TOKEN_REMAINING_MS=$((TOKEN_EXPIRES_AT_MS - NOW_MS))
  if [ "$TOKEN_REMAINING_MS" -le 0 ]; then
    echo "IMS token is already expired." >&2
    exit 1
  fi
  if [ "$TOKEN_REMAINING_MS" -lt 180000 ]; then
    echo "Warning: IMS token has less than 3 minutes remaining; deep crawl may fail mid-run." >&2
    format_unix_ms_utc "$TOKEN_EXPIRES_AT_MS" >&2 || true
  fi
fi

capture_tenant_scope_from_query "$INHERITED_QUERY"

extract_tenant_hint_from_payload() {
  local payload="$1"
  printf '%s' "$payload" | jq -r '
    def rows_from(x):
      if x == null then []
      elif (x | type) == "array" then x
      elif (x | type) == "object" then [x]
      else []
      end;
    [
      .. | objects | .report? | select(. != null)
      | rows_from(.)[]
      | select(type == "object")
      | (.tenant // .tenant_id // ."tenant-id" // .tenantId // .programmerId // .programmer_id // empty)
      | strings
      | gsub("^[[:space:]]+|[[:space:]]+$"; "")
      | select(length > 0)
    ][0] // empty
  ' 2>/dev/null || true
}

build_effective_query() {
  local path_query_raw="$1"
  local inherited_query_raw="${2:-}"
  local path_query merged

  path_query="$(sanitize_inherited_query "$path_query_raw")"
  capture_tenant_scope_from_query "$path_query"
  merged="$(merge_query_strings "$path_query" "$inherited_query_raw")"
  merged="$(merge_query_strings "$merged" "$INHERITED_QUERY")"
  if ! query_has_tenant_scope "$merged" && [ -n "${CMU_TENANT_SCOPE:-}" ]; then
    merged="$(query_add_kv "$merged" "tenant" "$CMU_TENANT_SCOPE")"
  fi
  merged="$(query_add_kv "$merged" "limit" "$CMU_CRAWL_ROW_LIMIT")"
  printf '%s' "$merged"
}

resolve_link_path() {
  local href="$1"
  local href_base

  case "$href" in
    http://*|https://*)
      href_base="$(base_url_from_absolute_url "$href" || true)"
      if [ -n "$href_base" ]; then
        printf '%s' "$(normalize_to_base_url "$href" "$href_base")"
      else
        printf '%s' "$(normalize_to_base_url "$href" "$CMU_PRIMARY_BASE_URL")"
      fi
      ;;
    *)
      printf '%s' "$(normalize_to_base_url "$href" "$CMU_PRIMARY_BASE_URL")"
      ;;
  esac
}

extract_hal_self_href() {
  local payload="$1"
  printf '%s' "$payload" | jq -r '
    [
      .. | objects | ._links?.self?.href? | select(type == "string" and length > 0)
    ][0] // empty
  ' 2>/dev/null || true
}

extract_hal_self_query() {
  local payload="$1"
  local self_href self_query

  self_href="$(extract_hal_self_href "$payload")"
  [ -n "$self_href" ] || return 0
  self_query="$(query_from_url "$self_href" || true)"
  sanitize_inherited_query "$self_query"
}

canonical_usage_path_key() {
  local raw="$1"
  local normalized normalized_lines part lower
  local normalized_parts=()
  local sorted_parts

  normalized="$(normalize_cmu_api_path "$raw")"
  normalized="${normalized%%\?*}"
  normalized="${normalized%.json}"
  normalized_lines="$(printf '%s' "${normalized#/}" | tr '/' '\n')"

  while IFS= read -r part || [ -n "$part" ]; do
    [ -n "$part" ] || continue
    lower="$(printf '%s' "$part" | tr '[:upper:]' '[:lower:]')"
    case "$lower" in
      cmu|v2) continue ;;
    esac
    normalized_parts+=("$lower")
  done <<< "$normalized_lines"

  if [ "${#normalized_parts[@]}" -eq 0 ]; then
    printf '%s' "$normalized"
    return 0
  fi

  sorted_parts="$(printf '%s\n' "${normalized_parts[@]}" | LC_ALL=C sort -u)"
  printf '/v2'
  while IFS= read -r part || [ -n "$part" ]; do
    [ -n "$part" ] || continue
    printf '/%s' "$part"
  done <<< "$sorted_parts"
}

cmu_usage_path_parts() {
  local raw="$1"
  local normalized normalized_lines part lower

  normalized="$(normalize_cmu_api_path "$raw")"
  normalized="${normalized%%\?*}"
  normalized="${normalized%.json}"
  normalized_lines="$(printf '%s' "${normalized#/}" | tr '/' '\n')"

  while IFS= read -r part || [ -n "$part" ]; do
    [ -n "$part" ] || continue
    lower="$(printf '%s' "$part" | tr '[:upper:]' '[:lower:]')"
    case "$lower" in
      cmu|v2) continue ;;
    esac
    printf '%s\n' "$lower"
  done <<< "$normalized_lines"
}

cmu_time_spine_level() {
  local raw="$1"
  local joined

  joined="$(cmu_usage_path_parts "$raw" | paste -sd'/' -)"
  case "$joined" in
    year) printf '1' ;;
    year/month) printf '2' ;;
    year/month/day) printf '3' ;;
    year/month/day/hour) printf '4' ;;
    *) printf '0' ;;
  esac
}

cmu_is_supported_time_spine_node() {
  local raw="$1"
  local level

  level="$(cmu_time_spine_level "$raw")"
  [ "$level" -ge 1 ] && [ "$level" -le 4 ]
}

cmu_is_next_time_spine_child() {
  local parent_raw="$1"
  local child_raw="$2"
  local parent_joined child_joined

  parent_joined="$(cmu_usage_path_parts "$parent_raw" | paste -sd'/' -)"
  child_joined="$(cmu_usage_path_parts "$child_raw" | paste -sd'/' -)"

  case "$parent_joined" in
    year) [ "$child_joined" = "year/month" ] ;;
    year/month) [ "$child_joined" = "year/month/day" ] ;;
    year/month/day) [ "$child_joined" = "year/month/day/hour" ] ;;
    *) return 1 ;;
  esac
}

path_visit_key() {
  canonical_usage_path_key "$1"
}

CMU_FETCH_URL=""
CMU_FETCH_STATUS=""
CMU_FETCH_PAYLOAD=""
CMU_FETCH_TRACE=""

fetch_json_live() {
  local path="$1"
  local inherited_query_raw="${2:-}"
  local clean_path="${path%%\?*}"
  local path_query="" merged_query query normalized_api_path
  local response status payload candidate base base_path absolute_base
  local candidates=()
  local bases=()
  local seen_bases="" seen_candidates=""
  local last_error_url="" last_error_status="" last_error_payload=""

  clean_path="${clean_path%.json}"
  if [[ "$path" == *\?* ]]; then
    path_query="${path#*\?}"
  fi

  merged_query="$(build_effective_query "$path_query" "$inherited_query_raw")"
  query="$(query_add_kv "$merged_query" "format" "json")"
  normalized_api_path="$(normalize_cmu_api_path "$clean_path")"

  add_base() {
    local next_base="$1"
    [ -n "$next_base" ] || return 0
    next_base="${next_base%/}"
    if [[ "$seen_bases" != *"|${next_base}|"* ]]; then
      seen_bases="${seen_bases}|${next_base}|"
      bases+=("$next_base")
    fi
  }

  add_candidate() {
    local next="$1"
    [ -n "$next" ] || return 0
    if [[ "$seen_candidates" != *"|${next}|"* ]]; then
      seen_candidates="${seen_candidates}|${next}|"
      candidates+=("$next")
    fi
  }

  absolute_base="$(base_url_from_absolute_url "$clean_path" || true)"
  add_base "$absolute_base"
  add_base "$CMU_PRIMARY_BASE_URL"
  if [ "$CMU_TRY_FALLBACK_BASE" = "1" ]; then
    add_base "$CMU_FALLBACK_BASE_URL"
  fi

  for base in "${bases[@]}"; do
    base_path="$(path_for_base_url "$base" "$normalized_api_path")"
    add_candidate "$(url_with_query "${base}${base_path}" "$query")"
    add_candidate "$(url_with_query "${base}${base_path}.json" "$merged_query")"
  done

  add_candidate "$(url_with_query "$clean_path" "$query")"
  add_candidate "$(url_with_query "${clean_path}.json" "$merged_query")"

  CMU_FETCH_TRACE=""
  for candidate in "${candidates[@]}"; do
    response="$(curl -sS -w $'\n%{http_code}' "${AUTH_HEADER_ARGS[@]}" "$candidate" || true)"
    if [[ "$response" == *$'\n'* ]]; then
      status="${response##*$'\n'}"
      payload="${response%$'\n'*}"
    else
      status="000"
      payload="$response"
    fi

    if [ -n "$CMU_FETCH_TRACE" ]; then
      CMU_FETCH_TRACE="${CMU_FETCH_TRACE}; ${status} ${candidate}"
    else
      CMU_FETCH_TRACE="${status} ${candidate}"
    fi

    if [[ "$status" =~ ^2[0-9][0-9]$ ]] && echo "$payload" | jq -e . >/dev/null 2>&1; then
      CMU_FETCH_URL="$candidate"
      CMU_FETCH_STATUS="$status"
      CMU_FETCH_PAYLOAD="$payload"
      return 0
    fi

    last_error_url="$candidate"
    last_error_status="$status"
    last_error_payload="$payload"
  done

  CMU_FETCH_URL="$last_error_url"
  CMU_FETCH_STATUS="$last_error_status"
  CMU_FETCH_PAYLOAD="$last_error_payload"
  return 1
}

append_discovered_entry() {
  local url="$1"
  local columns_json="$2"
  local columns_known="$3"

  jq -nc \
    --arg url "$url" \
    --argjson columns "$columns_json" \
    --argjson columnsKnown "$columns_known" \
    '{ url: $url, columns: $columns, columnsKnown: ($columnsKnown == 1) }' >> "$DISCOVERED_NDJSON"
}

extract_report_columns_json() {
  local payload="$1"
  printf '%s' "$payload" | jq -c '
    def visible_entries(row):
      row
      | to_entries
      | map(select((.key | startswith("__") | not) and (.value != null) and ((.value | type) != "string" or (.value | gsub("^[[:space:]]+|[[:space:]]+$"; "") | length) > 0)));
    def populated_rows:
      if (.report? | type) != "array" then []
      else
        [
          .report[]
          | select(type == "object")
          | select((visible_entries(.) | length) > 0)
        ]
      end;
    populated_rows as $rows
    | if ($rows | length) == 0 then
        []
      else
        [
          $rows[]
          | keys[]
          | select(startswith("__") | not)
        ] | unique
      end
  ' 2>/dev/null || printf '[]'
}

payload_has_report_candidate() {
  local payload="$1"
  printf '%s' "$payload" | jq -e '
    def visible_entries(row):
      row
      | to_entries
      | map(select((.key | startswith("__") | not) and (.value != null) and ((.value | type) != "string" or (.value | gsub("^[[:space:]]+|[[:space:]]+$"; "") | length) > 0)));
    (.report? | type) == "array"
    and any(.report[]?; (type == "object") and ((visible_entries(.) | length) > 0))
  ' >/dev/null 2>&1
}

extract_hal_child_hrefs() {
  local payload="$1"
  printf '%s' "$payload" | jq -r '
    def rel_is_drill:
      (ascii_downcase) as $rel
      | ($rel == "drill-down"
        or $rel == "drill_down"
        or $rel == "drilldown");
    def href_from_link_object:
      if type != "object" then empty
      else
        (.href // empty) as $href
        | if ($href | type) != "string" then empty
          elif ((.templated // false) == true) and ($href | test("\\{")) then empty
          else $href
          end
      end;
    def hrefs_from(value):
      if value == null then empty
      elif (value | type) == "array" then value[]
      else value
      end
      | href_from_link_object;
    (._links? // {} | to_entries[]? | select(.key | rel_is_drill) | .value | hrefs_from(.))
    | strings | select(length > 0)
  ' 2>/dev/null || true
}

CMU_VISITED_KEYS="|"
CMU_ABORT_CRAWL=0
CMU_TOKEN_EXPIRY_NOTICE_EMITTED=0

token_expiry_window_reached() {
  local now_ms buffer_ms threshold_ms

  [[ "${TOKEN_EXPIRES_AT_MS:-}" =~ ^[0-9]+$ ]] || return 1
  [[ "${CMU_STOP_BEFORE_TOKEN_EXPIRY_MS:-}" =~ ^[0-9]+$ ]] || return 1

  now_ms=$(( $(date +%s) * 1000 ))
  buffer_ms="$CMU_STOP_BEFORE_TOKEN_EXPIRY_MS"
  threshold_ms=$((TOKEN_EXPIRES_AT_MS - buffer_ms))
  [ "$now_ms" -ge "$threshold_ms" ]
}

process_json() {
  local path="$1"
  local inherited_query_raw="${2:-}"
  local canonical_key canonical_href response source_url error_status auth_error
  local columns_json columns_known child_links child_path child_query_raw child_visit_key link node_query_raw

  if [ "$CMU_ABORT_CRAWL" = "1" ]; then
    return 0
  fi

  if token_expiry_window_reached; then
    if [ "$CMU_TOKEN_EXPIRY_NOTICE_EMITTED" = "0" ]; then
      echo "Stopping crawl before IMS token expiry window to keep the generated map clean." >&2
      echo "The exported clickCMU still uses UnderPAR token refresh code at runtime." >&2
      CMU_TOKEN_EXPIRY_NOTICE_EMITTED=1
    fi
    CMU_ABORT_CRAWL=1
    return 0
  fi

  canonical_key="$(path_visit_key "$path")"
  canonical_href="$(normalize_to_base_url "$path" "$CMU_REPORTS_BASE_URL")"
  if [[ "$CMU_VISITED_KEYS" == *"|${canonical_key}|"* ]]; then
    return 0
  fi
  CMU_VISITED_KEYS="${CMU_VISITED_KEYS}${canonical_key}|"

  progress_tick

  if fetch_json_live "$path" "$inherited_query_raw"; then
    response="$CMU_FETCH_PAYLOAD"
    source_url="$CMU_FETCH_URL"
    capture_tenant_scope_from_url "$source_url"
    capture_tenant_scope_candidate "$(extract_tenant_hint_from_payload "$response")"
    SUCCESS_COUNT=$((SUCCESS_COUNT + 1))
    if payload_has_report_candidate "$response"; then
      columns_json="$(extract_report_columns_json "$response")"
      columns_known=1
      append_discovered_entry "$source_url" "$columns_json" "$columns_known"
    fi
    node_query_raw="$(extract_hal_self_query "$response")"
    if [ -z "$node_query_raw" ]; then
      node_query_raw="$(sanitize_inherited_query "$(query_from_url "$source_url" || true)")"
    fi

    child_links="$(extract_hal_child_hrefs "$response" | awk '!seen[$0]++')"
    while IFS= read -r link || [ -n "$link" ]; do
      [ -n "$link" ] || continue
      if [ "$CMU_ABORT_CRAWL" = "1" ]; then
        break
      fi
      capture_tenant_scope_from_url "$link"
      child_query_raw="$(merge_query_strings "$(query_from_url "$link" || true)" "$(sanitize_drill_context_query "$node_query_raw")")"
      child_path="$(resolve_link_path "$link")"
      child_visit_key="$(path_visit_key "$child_path")"
      if [[ "$CMU_VISITED_KEYS" == *"|${child_visit_key}|"* ]]; then
        continue
      fi
      process_json "$child_path" "$child_query_raw"
    done <<< "$child_links"
    return 0
  fi

  error_status="${CMU_FETCH_STATUS:-000}"
  source_url="${CMU_FETCH_URL:-$path}"
  auth_error=0
  echo "HTTP ${error_status} from ${source_url}" >&2
  [ -n "${CMU_FETCH_PAYLOAD:-}" ] && echo "$CMU_FETCH_PAYLOAD" >&2
  if [ "$error_status" = "401" ] || echo "${CMU_FETCH_PAYLOAD:-}" | grep -Eqi 'invalid_token|Invalid or expired token|ims/profile/v1'; then
    auth_error=1
    echo "Hint: token is invalid/expired for CMU profile checks. The exported clickCMU can refresh later, but the live crawl is stopping now." >&2
    if [ "$CMU_FAIL_FAST_AUTH_ERRORS" = "1" ]; then
      echo "Aborting crawl early because auth is failing (CMU_FAIL_FAST_AUTH_ERRORS=1)." >&2
      CMU_ABORT_CRAWL=1
    fi
  fi
  if [ "$auth_error" = "1" ] && [ "$CMU_SUPPRESS_AUTH_ERROR_NODES" = "1" ]; then
    return 0
  fi
  FAIL_COUNT=$((FAIL_COUNT + 1))
}

jq -s '.' "$DISCOVERED_NDJSON" > "$DISCOVERED_JSON"
process_json "$START_PATH"
jq -s '.' "$DISCOVERED_NDJSON" > "$DISCOVERED_JSON"

if [ "$SUCCESS_COUNT" -gt 0 ]; then
  cp "$DISCOVERED_JSON" "$RENDER_DISCOVERED_JSON"
else
  printf '[]\n' > "$RENDER_DISCOVERED_JSON"
fi

if [ "$SUCCESS_COUNT" -eq 0 ] && [ ! -f "${CMU_CLICK_FALLBACK_CATALOG:-}" ]; then
  echo "No successful CMU nodes were retrieved and no fallback endpoint catalog is available." >&2
  exit 3
fi

if [ -z "${CMU_TENANT_SCOPE:-}" ] && [ -n "${CMU_PROGRAMMER_ID:-}" ]; then
  CMU_TENANT_SCOPE="$CMU_PROGRAMMER_ID"
fi
if [ -z "${CMU_TENANT_SCOPE:-}" ]; then
  echo "Unable to infer the CMU tenant/programmer scope from the start URL or live HAL responses." >&2
  echo "Pass a CMU URL with tenant=..., use a legacy tenant path, or set CMU_PROGRAMMER_ID/CMU_PROGRAMMER_LABEL explicitly." >&2
  exit 2
fi
if [ -z "${CMU_PROGRAMMER_ID:-}" ]; then
  CMU_PROGRAMMER_ID="$CMU_TENANT_SCOPE"
fi
if [ -z "${CMU_PROGRAMMER_LABEL:-}" ]; then
  CMU_PROGRAMMER_LABEL="$CMU_PROGRAMMER_ID"
fi

RENDER_ARGS=(
  "$CMU_RENDER_HELPER"
  --template "$CMU_CLICK_TEMPLATE_HTML"
  --runtime-patch "$CMU_RUNTIME_PATCH_HTML"
  --discovered "$RENDER_DISCOVERED_JSON"
  --access-token "$TOKEN"
  --client-id "$IMS_CLIENT_ID"
  --programmer-id "${CMU_PROGRAMMER_ID:-$CMU_TENANT_SCOPE}"
  --programmer-label "$CMU_PROGRAMMER_LABEL"
  --theme-scope "${CMU_PROGRAMMER_ID:-$CMU_PROGRAMMER_LABEL}"
  --user-id "$IMS_USER_ID"
  --scope "$IMS_SCOPE"
  --tenant-scope "$CMU_TENANT_SCOPE"
)
if [ "$SUCCESS_COUNT" -eq 0 ] && [ -n "${CMU_CLICK_FALLBACK_CATALOG:-}" ] && [ -f "$CMU_CLICK_FALLBACK_CATALOG" ]; then
  RENDER_ARGS+=(--fallback "$CMU_CLICK_FALLBACK_CATALOG")
fi

node "${RENDER_ARGS[@]}" > "$OUTPUT_HTML"
cat "$OUTPUT_HTML"

if [ "$SUCCESS_COUNT" -eq 0 ]; then
  echo "No live CMU node responses were retrieved. The generated HTML was built from the canonical UnderPAR endpoint catalog only." >&2
fi

if [ "$CMU_ABORT_CRAWL" = "1" ]; then
  echo "Crawl ended early (token expiry/auth guard). Generated HTML is still usable for click-run." >&2
fi
